void insert()
{

    if (this.PaymentType == IWS_PaymentType::Reimburse)
    {
        TrvExpTable trvExpTable = TrvExpTable::find(this.ExpNumber);

        if (trvExpTable.QYGD_OAExpenseNum)
        {
            this.QYGD_PaymentMethod = trvExpTable.QYGD_PaymentMethod;
            this.QYGD_OAExpenseNum  = trvExpTable.QYGD_OAExpenseNum;
        }
    }
    next insert();
}
